local buf, win = H.open()
vim.api.nvim_win_set_cursor(win, { 1, 0 })
vim.cmd("2,4Revisa comment")
local editor = H.reserved(buf, win, 4)
vim.api.nvim_buf_set_lines(editor, 0, -1, false, { "Range comment" })
vim.cmd("write")
assert(not H.padding(buf), "padding remains after save")
H.equal(win, vim.api.nvim_get_current_win())
H.display(buf, 2, 4, { "Range comment" })
